fs.writeSync = function (fd, buf, o, l, pos) {
  if ((pos === null || pos === undefined) && fd > 2 && typeof buf !== 'string') {
    const p = filePos.get(fd) || 0;
    const n = rawWrite(fd, buf, o, l, p);
