      case 0x20: r[rt] = mem8s[(r[rs] + imm) >>> 0]; break;                    // lb
      case 0x21: r[rt] = mem16s[((r[rs] + imm) >>> 0) >> 1]; break;            // lh
      case 0x22: { // lwl
        const a = (r[rs] + imm) >>> 0;
        const al = a & 3;
        const w = mem32[(a & ~3) >>> 2];
        const sh = (3 - al) * 8;
        const mask = sh === 0 ? 0 : (-1 >>> (32 - sh));
        r[rt] = ((w << sh) | (r[rt] & mask)) | 0;
        break;
      }
      case 0x23: r[rt] = mem32[((r[rs] + imm) >>> 0) >>> 2]; break;            // lw
      case 0x24: r[rt] = mem8[(r[rs] + imm) >>> 0]; break;                     // lbu
      case 0x25: r[rt] = mem16[((r[rs] + imm) >>> 0) >> 1]; break;             // lhu
      case 0x26: { // lwr
        const a = (r[rs] + imm) >>> 0;
        const al = a & 3;
        const w = mem32[(a & ~3) >>> 2];
        const sh = al * 8;
        const mask = sh === 0 ? 0 : (-1 << (32 - sh));
        r[rt] = ((w >>> sh) | (r[rt] & mask)) | 0;
        break;
      }
      case 0x28: mem8[(r[rs] + imm) >>> 0] = r[rt]; break;                     // sb
      case 0x29: mem16[((r[rs] + imm) >>> 0) >> 1] = r[rt]; break;             // sh
      case 0x2a: { // swl
        const a = (r[rs] + imm) >>> 0;
        const al = a & 3;
        const idx = (a & ~3) >>> 2;
        const sh = (3 - al) * 8;
        const keep = sh === 0 ? 0 : (-1 << (32 - sh));
        mem32[idx] = ((mem32[idx] & keep) | (r[rt] >>> sh)) | 0;
        break;
      }
      case 0x2b: mem32[((r[rs] + imm) >>> 0) >>> 2] = r[rt]; break;            // sw
      case 0x2e: { // swr
        const a = (r[rs] + imm) >>> 0;
        const al = a & 3;
        const idx = (a & ~3) >>> 2;
        const sh = al * 8;
        const keep = sh === 0 ? 0 : (-1 >>> (32 - sh));
        mem32[idx] = ((mem32[idx] & keep) | (r[rt] << sh)) | 0;
        break;
      }
      case 0x2f: break;                                                        // cache
      case 0x30: r[rt] = mem32[((r[rs] + imm) >>> 0) >>> 2]; break;            // ll
      case 0x38: mem32[((r[rs] + imm) >>> 0) >>> 2] = r[rt]; r[rt] = 1; break;  // sc
      case 0x31: fgrS[rt] = mem32[((r[rs] + imm) >>> 0) >>> 2]; break;         // lwc1
      case 0x39: mem32[((r[rs] + imm) >>> 0) >>> 2] = fgrS[rt]; break;         // swc1
      case 0x35: { // ldc1
        const a = (r[rs] + imm) >>> 0;
        fgrS[rt & ~1] = mem32[a >>> 2];
        fgrS[(rt & ~1) | 1] = mem32[(a + 4) >>> 2];
        break;
      }
      case 0x3d: { // sdc1
        const a = (r[rs] + imm) >>> 0;
        mem32[a >>> 2] = fgrS[rt & ~1];
        mem32[(a + 4) >>> 2] = fgrS[(rt & ~1) | 1];
        break;
      }
      case 0x33: break;                                                        // pref
      default:
        trap('unknown opcode 0x' + op.toString(16) + ' (inst 0x' +
          (inst >>> 0).toString(16) + ')');
    }
    r[0] = 0;
  }
}

if (VERBOSE) {
  log('loaded ' + elfPath + ': entry 0x' + eh.entry.toString(16) +
    ', memory ' + (MEM_SIZE / (1024 * 1024)).toFixed(0) + ' MiB, gp 0x' +
    (r[28] >>> 0).toString(16) + ', sp 0x' + (r[29] >>> 0).toString(16));
}

try {
  run();
} catch (e) {
  if (!exiting) {
    log('fatal: ' + (e && e.stack ? e.stack : e));
    log('  pc=' + symbolize(pc - 4) + ' instructions=' + instCount);
    process.exit(70);
  }
}

